import{TabNav}from"./components/TabNav.js";import{DynastyTimeline}from"./components/DynastyTimeline.js";import{DynastyCardsList}from"./components/DynastyCard.js";import{DynastyMap}from"./components/DynastyMap.js";import{Contributions}from"./components/Contributions.js";import{dynasties,eraInfo}from"./data.js";const tabs=[{id:"all",label:"All Dynasties"},{id:"ancient",label:"Ancient"},{id:"medieval",label:"Medieval"},{id:"early-modern",label:"Early Modern"},{id:"timeline",label:"Timeline"},{id:"map",label:"Map"},{id:"contributions",label:"Contributions"}];let activeTab="all";function render(){const e=document.getElementById("dynasties-app");e.innerHTML="";const a=document.createElement("div");a.className="page-header",a.innerHTML="\n    <h1>Indian Dynasties Explorer</h1>\n    <p>Journey through India's most powerful empires — from the Mauryas to the Mughals — exploring their rulers, territories, art, and enduring contributions to civilization.</p>\n  ",e.appendChild(a);const n=document.createElement("div");n.appendChild(TabNav({tabs:tabs,activeTab:activeTab,onTabChange:e=>{activeTab=e,render()}})),e.appendChild(n);const t=document.createElement("div");if(t.className="dynasty-content",t.id=`panel-${activeTab}`,"timeline"===activeTab)t.appendChild(DynastyTimeline());else if("map"===activeTab)t.appendChild(DynastyMap());else if("contributions"===activeTab)t.appendChild(Contributions());else{const e="all"===activeTab?null:eraInfo[activeTab];if(e){const a=document.createElement("div");a.className="era-badge",a.innerHTML=`<span class="era-dot" style="background:${e.color}"></span> ${e.label} — ${e.description}`,t.appendChild(a)}t.appendChild(DynastyCardsList({era:activeTab}))}e.appendChild(t)}render();